changeSet.sql:
ALTER TABLE shipment_dangerous_good ADD COLUMN IF NOT EXISTS operator_id BIGINT;
UPDATE shipment_dangerous_good dangerous_good
SET operator_id = shipment.operator_id
FROM shipment
WHERE dangerous_good.shipment_id = shipment.shipment_id;
ALTER TABLE shipment_dangerous_good ALTER COLUMN operator_id SET NOT NULL;

ALTER TABLE shipment_dangerous_good_aud ADD COLUMN IF NOT EXISTS operator_id BIGINT;
UPDATE shipment_dangerous_good_aud dangerous_good
SET operator_id = shipment.operator_id
FROM shipment
WHERE dangerous_good.shipment_id = shipment.shipment_id;
